CREATE TABLE IF NOT EXISTS messages (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, body TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS expenses (id INTEGER PRIMARY KEY AUTOINCREMENT, day INTEGER NOT NULL, item INTEGER NOT NULL, title TEXT NOT NULL, amount REAL NOT NULL, currency TEXT NOT NULL, payer TEXT NOT NULL, split TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS recs (id INTEGER PRIMARY KEY AUTOINCREMENT, cat TEXT NOT NULL, name TEXT NOT NULL, en TEXT, why TEXT, warn TEXT, shops TEXT NOT NULL, place TEXT, author TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rec_likes (rec_id INTEGER NOT NULL, voter TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY (rec_id, voter));
CREATE TABLE IF NOT EXISTS room_assign (name TEXT PRIMARY KEY, room INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS settle_paid (name TEXT PRIMARY KEY, amount INTEGER NOT NULL, dir TEXT NOT NULL, paid_at INTEGER NOT NULL);
-- 領隊後台
CREATE TABLE IF NOT EXISTS leader_ledger (
  id INTEGER PRIMARY KEY AUTOINCREMENT, day INTEGER, item INTEGER, spent_on TEXT,
  category TEXT NOT NULL, vendor TEXT NOT NULL, place TEXT, content TEXT,
  currency TEXT NOT NULL, amount_local REAL NOT NULL, rate REAL, amount_twd REAL NOT NULL,
  twd_manual INTEGER NOT NULL DEFAULT 0, payer TEXT NOT NULL, method TEXT NOT NULL, note TEXT,
  status TEXT NOT NULL DEFAULT 'confirmed', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS receipts (
  id INTEGER PRIMARY KEY AUTOINCREMENT, ledger_id INTEGER, img BLOB NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL,
  ai_status TEXT NOT NULL DEFAULT 'pending', ai_json TEXT, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS leader_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts (ip TEXT NOT NULL, at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ai_usage (day TEXT PRIMARY KEY, calls INTEGER NOT NULL, neurons REAL NOT NULL);
